#include <cstdint>
#include <iostream>
int main() {
    const std::uint64_t whole = 0x1234;
    const auto low = whole & 0xffu;
    const auto next = (whole >> 8) & 0xffu;
    const auto after_byte = (whole & ~std::uint64_t{0xff}) | 0xabu;
    std::cout << "low=" << low << " next=" << next << '\n';
    std::cout << std::hex << "after-byte=" << after_byte << '\n';
}

#include <bit>
#include <cstdint>
#include <iostream>
#include <limits>
int main() {
    const std::uint8_t bits = std::numeric_limits<std::uint8_t>::max();
    const auto signed_value = std::bit_cast<std::int8_t>(bits);
    std::cout << std::boolalpha
              << "signed-less=" << (signed_value < 1)
              << " unsigned-less=" << (bits < 1u) << '\n';
}
